644	    /// Handle a prompt decision. Returns `Some(StepAction)` if the step should
645	    /// not proceed to execution (user declined), or `None` to fall through.
646	    #[allow(clippy::too_many_arguments)]
647	    fn handle_prompt(
648	        &self,
649	        prompt_key: &str,
650	        eval_result: &EvaluationResult,
651	        step_pad: &str,
652	        _needs_force: bool,
653	        event_bus: &mut EventBus,
654	        ui: &mut dyn UserInterface,
655	        step_display: &mut dyn StepDisplay,
656	    ) -> Result<Option<StepAction>> {
657	        if prompt_key.starts_with("rerun_") {
658	            let prompt_text = format!("{}. Run again?", eval_result.reason);
659	            let prompt = Prompt {
660	                key: prompt_key.to_string(),
661	                question: format!("{}{}", step_pad, prompt_text),
662	                prompt_type: PromptType::Select {
663	                    options: vec![
664	                        PromptOption {
665	                            label: "No  (n)".to_string(),
666	                            value: "no".to_string(),
667	                        },
668	                        PromptOption {
669	                            label: "Yes (y)".to_string(),
670	                            value: "yes".to_string(),
671	                        },
672	                    ],
673	                },
674	                default: Some("no".to_string()),
675	            };
676	            let answer = ui.prompt(&prompt)?;
677	            // clear_lines removed — surface tracks regions
678	            if answer.as_string() != "yes" {
679	                event_bus.emit(&BivvyEvent::StepSkipped {
680	                    name: self.step_name.to_string(),
681	                    reason: eval_result.reason.clone(),
682	                });
683	                event_bus.emit(&BivvyEvent::StepOutcome {
684	                    name: self.step_name.to_string(),
685	                    outcome: StepOutcomeKind::Satisfied,
686	                    detail: Some(eval_result.reason.clone()),
687	                    duration_ms: None,
688	                });
689	                let skip_label = crate::ui::satisfaction_label(&eval_result.reason);
690	                step_display.message(&format!(
691	                    "{}{}",
692	                    step_pad,
693	                    StatusKind::Success.format(self.theme, &skip_label)
694	                ));
695	                return Ok(Some(StepAction::Skipped(
696	                    StepResult::check_passed(
697	                        &self.step.name,
698	                        CheckResult::passed(eval_result.reason.clone()),
699	                    ),
700	                    SkipCategory::Satisfied,
701	                )));
702	            }
703	            // User chose yes — fall through to execution
704	        } else if prompt_key.starts_with("autorun_") {
705	            let prompt_text = format!("Run {}?", self.step.title);
706	            let prompt = Prompt {
707	                key: prompt_key.to_string(),
708	                question: format!("{}{}", step_pad, prompt_text),
709	                prompt_type: PromptType::Select {
710	                    options: vec![
711	                        PromptOption {
712	                            label: "Yes (y)".to_string(),
713	                            value: "yes".to_string(),
714	                        },
715	                        PromptOption {
716	                            label: "No  (n)".to_string(),
717	                            value: "no".to_string(),
718	                        },
719	                    ],
720	                },
721	                default: Some("yes".to_string()),
722	            };
723	            event_bus.emit(&BivvyEvent::UserPrompted {
724	                step: Some(self.step_name.to_string()),
725	                prompt: prompt_text,
726	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
727	            });
728	            let answer = ui.prompt(&prompt)?;
729	            let answer_str = answer.as_string();
730	            event_bus.emit(&BivvyEvent::UserResponded {
731	                step: Some(self.step_name.to_string()),
732	                input: answer_str.clone(),
733	                method: crate::logging::InputMethod::ArrowSelect,
734	            });
735	            if answer_str != "yes" {
736	                // clear_lines removed — surface tracks regions
737	                event_bus.emit(&BivvyEvent::StepDecided {
738	                    name: self.step_name.to_string(),
739	                    decision: "skip".to_string(),
740	                    reason: Some("user_declined_auto_run".to_string()),
741	                    trace: None,
742	                });
743	                event_bus.emit(&BivvyEvent::StepSkipped {
744	                    name: self.step_name.to_string(),
745	                    reason: "user_declined_auto_run".to_string(),
746	                });
747	                event_bus.emit(&BivvyEvent::StepOutcome {
748	                    name: self.step_name.to_string(),
749	                    outcome: StepOutcomeKind::Declined,
750	                    detail: Some("user_declined_auto_run".to_string()),
751	                    duration_ms: None,
752	                });
753	                step_display.message(&format!(
754	                    "{}{}",
755	                    step_pad,
756	                    self.theme.format_skipped("Skipped")
757	                ));
758	                return Ok(Some(StepAction::Skipped(
759	                    StepResult::skipped(
760	                        &self.step.name,
761	                        CheckResult::passed("User declined to run"),
762	                    ),
763	                    SkipCategory::UserDeclined,
764	                )));
765	            }
766	            // clear_lines removed — surface tracks regions
767	        } else if prompt_key.starts_with("confirm_") {
768	            let prompt_text = format!("{}?", self.step.title);
769	            let prompt = Prompt {
770	                key: prompt_key.to_string(),
771	                question: format!("{}{}", step_pad, prompt_text),
772	                prompt_type: PromptType::Select {
773	                    options: vec![
774	                        PromptOption {
775	                            label: "Yes (y)".to_string(),
776	                            value: "yes".to_string(),
777	                        },
778	                        PromptOption {
779	                            label: "No  (n)".to_string(),
780	                            value: "no".to_string(),
781	                        },
782	                    ],
783	                },
784	                default: Some("yes".to_string()),
785	            };
786	            event_bus.emit(&BivvyEvent::UserPrompted {
787	                step: Some(self.step_name.to_string()),
788	                prompt: prompt_text,
789	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
790	            });
791	            let answer = ui.prompt(&prompt)?;
792	            let answer_str = answer.as_string();
793	            event_bus.emit(&BivvyEvent::UserResponded {
794	                step: Some(self.step_name.to_string()),
795	                input: answer_str.clone(),
796	                method: crate::logging::InputMethod::ArrowSelect,
797	            });
798	            if answer_str != "yes" {
799	                // clear_lines removed — surface tracks regions
800	                event_bus.emit(&BivvyEvent::StepDecided {
801	                    name: self.step_name.to_string(),
802	                    decision: "skip".to_string(),
803	                    reason: Some("user_declined".to_string()),
804	                    trace: None,
805	                });
806	                event_bus.emit(&BivvyEvent::StepSkipped {
807	                    name: self.step_name.to_string(),
808	                    reason: "user_declined".to_string(),
809	                });
810	                event_bus.emit(&BivvyEvent::StepOutcome {
811	                    name: self.step_name.to_string(),
812	                    outcome: StepOutcomeKind::Declined,
813	                    detail: Some("user_declined".to_string()),
814	                    duration_ms: None,
815	                });
816	                step_display.message(&format!(
817	                    "{}{}",
818	                    step_pad,
819	                    self.theme.format_skipped("Skipped")
820	                ));
821	                return Ok(Some(StepAction::Skipped(
822	                    StepResult::skipped(&self.step.name, CheckResult::passed("User declined")),
823	                    SkipCategory::UserDeclined,
824	                )));
825	            }
826	            // clear_lines removed — surface tracks regions
827	        } else if prompt_key.starts_with("sensitive_") {
828	            let prompt_text = "Handles sensitive data. Continue?";
829	            let prompt = Prompt {
830	                key: prompt_key.to_string(),
831	                question: prompt_text.to_string(),
832	                prompt_type: PromptType::Select {
833	                    options: vec![
834	                        PromptOption {
835	                            label: "Yes (y)".to_string(),
836	                            value: "yes".to_string(),
837	                        },
838	                        PromptOption {
839	                            label: "No (n)".to_string(),
840	                            value: "no".to_string(),
841	                        },
842	                    ],
843	                },
844	                default: Some("yes".to_string()),
845	            };
846	            event_bus.emit(&BivvyEvent::UserPrompted {
847	                step: Some(self.step_name.to_string()),
848	                prompt: prompt_text.to_string(),
849	                options: vec!["Yes (y)".to_string(), "No (n)".to_string()],
850	            });
851	            let answer = ui.prompt(&prompt)?;
852	            let answer_str = answer.as_string();
853	            event_bus.emit(&BivvyEvent::UserResponded {
854	                step: Some(self.step_name.to_string()),
855	                input: answer_str.clone(),
856	                method: crate::logging::InputMethod::ArrowSelect,
857	            });
858	            if answer_str != "yes" {
859	                if self.step.behavior.skippable {
860	                    event_bus.emit(&BivvyEvent::StepSkipped {
861	                        name: self.step_name.to_string(),
862	                        reason: "user_declined_sensitive".to_string(),
863	                    });
864	                    event_bus.emit(&BivvyEvent::StepOutcome {
865	                        name: self.step_name.to_string(),
866	                        outcome: StepOutcomeKind::Declined,
867	                        detail: Some("user_declined_sensitive".to_string()),
868	                        duration_ms: None,
869	                    });
870	                    step_display.message(&format!(
871	                        "{}{}",
872	                        step_pad,
873	                        self.theme
874	                            .format_skipped("Skipped (declined sensitive step)")
875	                    ));
876	                    return Ok(Some(StepAction::Skipped(
877	                        StepResult::skipped(
878	                            &self.step.name,
879	                            CheckResult::passed("User declined sensitive step"),
880	                        ),
881	                        SkipCategory::UserDeclined,
882	                    )));
883	                } else {
884	                    return Err(BivvyError::StepExecutionError {
885	                        step: self.step_name.to_string(),
886	                        message: format!(
887	                            "Step '{}' is sensitive and not skippable, but user declined",
888	                            self.step.title
889	                        ),
890	                    });
891	                }
892	            }
893	            // User chose yes — fall through to execution
894	        }
895	
896	        Ok(None) // Fall through to execution
897	    }
898	}
899	
900	/// Map a [`SkipReason`] (produced by the decision engine) to the typed
901	/// terminal [`StepOutcomeKind`] it represents.
902	///
903	/// `SkipReason::AutoSatisfied` is handled by `handle_auto_satisfied` and
904	/// never reaches the generic skip fall-through, but we map it here for
905	/// completeness so a future caller cannot misroute it.
906	fn skip_reason_to_outcome(reason: &SkipReason) -> StepOutcomeKind {
907	    match reason {
908	        SkipReason::CheckPassed | SkipReason::Satisfied | SkipReason::AutoSatisfied => {
909	            StepOutcomeKind::Satisfied
910	        }
911	        SkipReason::UserDeclined | SkipReason::SensitiveDeclined => StepOutcomeKind::Declined,
912	        SkipReason::RequirementNotMet => StepOutcomeKind::Blocked,
913	    }
914	}
915	
916	/// Drain pending baseline events from the snapshot store and emit them on the event bus.
917	fn emit_baseline_events(snapshot_store: &mut SnapshotStore, event_bus: &mut EventBus) {
918	    for evt in snapshot_store.drain_events() {
919	        match evt.change {
920	            crate::snapshots::BaselineChange::Established => {
921	                event_bus.emit(&BivvyEvent::BaselineEstablished {
922	                    step: evt.step,
923	                    target: evt.target,
924	                    hash: evt.hash,
925	                    scope: evt.scope,
926	                });
927	            }
928	            crate::snapshots::BaselineChange::Updated { old_hash } => {
929	                event_bus.emit(&BivvyEvent::BaselineUpdated {
930	                    step: evt.step,
931	                    target: evt.target,
932	                    old_hash,
933	                    new_hash: evt.hash,
934	                });
935	            }
936	            crate::snapshots::BaselineChange::Unchanged => {}
937	        }
938	    }
939	}
940	
941	/// Build behavior flags from a resolved step and force status.
942	fn make_behavior_flags(step: &ResolvedStep, forced: bool) -> BehaviorFlags {
943	    BehaviorFlags {
944	        skippable: step.behavior.skippable,
945	        required: step.behavior.required,
946	        forced,
947	        auto_run: step.behavior.auto_run,
948	        prompt_on_rerun: step.behavior.prompt_on_rerun,
949	        confirm: step.behavior.confirm,
950	    }
951	}
952	
953	#[cfg(test)]
954	mod tests {
955	    use super::*;
956	    use crate::steps::{
957	        ResolvedBehavior, ResolvedEnvironmentVars, ResolvedExecution, ResolvedHooks,
958	        ResolvedOutput, ResolvedScoping,
959	    };
960	
961	    fn dummy_step(name: &str) -> ResolvedStep {
962	        ResolvedStep {
963	            name: name.to_string(),
964	            title: name.to_string(),
965	            description: None,
966	            depends_on: vec![],
967	            requires: vec![],
968	            inputs: HashMap::new(),
969	            satisfied_when: vec![],
970	            execution: ResolvedExecution::default(),
971	            env_vars: ResolvedEnvironmentVars::default(),
972	            behavior: ResolvedBehavior::default(),
973	            hooks: ResolvedHooks::default(),
974	            output: ResolvedOutput::default(),
975	            scoping: ResolvedScoping::default(),
976	        }
977	    }
978	
979	    /// `step_indent` must match the rendered step number width plus a single
980	    /// space — so error blocks, status lines, and recovery prompts align under
981	    /// the step name.
982	    #[test]
983	    fn step_indent_matches_step_number_width() {
984	        let step = dummy_step("setup");
985	        let theme = BivvyTheme::new();
986	
987	        // [1/3] = 5 chars + space = 6
988	        let mgr = StepManager::new(&step, "setup", 0, 3, &theme);
989	        assert_eq!(mgr.step_number(), "[1/3]");
990	        assert_eq!(mgr.step_indent(), 6);
991	        assert_eq!(mgr.step_pad(), "      ");
992	
993	        // [10/15] = 7 chars + space = 8
994	        let mgr = StepManager::new(&step, "setup", 9, 15, &theme);
995	        assert_eq!(mgr.step_number(), "[10/15]");
996	        assert_eq!(mgr.step_indent(), 8);
997	        assert_eq!(mgr.step_pad(), "        ");
998	
999	        // [1/1] = 5 chars + space = 6
1000	        let mgr = StepManager::new(&step, "setup", 0, 1, &theme);
1001	        assert_eq!(mgr.step_number(), "[1/1]");
1002	        assert_eq!(mgr.step_indent(), 6);
1003	
1004	        // [100/100] = 9 chars + space = 10
1005	        let mgr = StepManager::new(&step, "setup", 99, 100, &theme);
1006	        assert_eq!(mgr.step_number(), "[100/100]");
1007	        assert_eq!(mgr.step_indent(), 10);
1008	    }
1009	}
