382	/// Shared buffer between [`MockWorkflowDisplay`] and the
383	/// [`MockStepDisplay`]s it spawns. Tests can read this through the
384	/// workflow display to assert on every captured interaction.
385	#[derive(Default)]
386	pub struct MockState {
387	    /// Run headers shown.
388	    pub headers: Vec<RunHeader>,
389	    /// Run summaries shown.
390	    pub summaries: Vec<RunSummary>,
391	    /// Workflow progress events (current, total, elapsed).
392	    pub progress_events: Vec<(usize, usize, Duration)>,
393	    /// Workflow-level messages (above the progress region).
394	    pub workflow_messages: Vec<String>,
395	    /// Workflow-level hints.
396	    pub workflow_hints: Vec<String>,
397	    /// Per-step messages captured from `MockStepDisplay`.
398	    pub step_messages: Vec<String>,
399	    /// Per-step warnings.
400	    pub step_warnings: Vec<String>,
401	    /// Per-step error blocks (command, output, hint, indent).
402	    pub step_error_blocks: Vec<(String, String, Option<String>, usize)>,
403	    /// Per-step success lines (formatted).
404	    pub step_successes: Vec<String>,
405	    /// Per-step error lines (formatted).
406	    pub step_errors: Vec<String>,
407	    /// Per-step skipped lines (formatted).
408	    pub step_skipped: Vec<String>,
409	}
