411	/// In-memory workflow display for tests.
412	///
413	/// Captures every interaction (workflow- and step-level) so assertions
414	/// can be made without depending on stdout capture.
415	pub struct MockWorkflowDisplay {
416	    state: Rc<RefCell<MockState>>,
417	}
418	
419	impl Default for MockWorkflowDisplay {
420	    fn default() -> Self {
421	        Self::new()
422	    }
423	}
424	
425	impl MockWorkflowDisplay {
426	    /// Construct a new mock workflow display.
427	    pub fn new() -> Self {
428	        Self {
429	            state: Rc::new(RefCell::new(MockState::default())),
430	        }
431	    }
432	
433	    /// Borrow the captured state for assertions.
434	    pub fn state(&self) -> std::cell::Ref<'_, MockState> {
435	        self.state.borrow()
436	    }
437	
438	    /// Whether any captured message contains `needle`. Searches across
439	    /// workflow- and step-level messages.
440	    pub fn has_message(&self, needle: &str) -> bool {
441	        let s = self.state.borrow();
442	        s.workflow_messages.iter().any(|m| m.contains(needle))
443	            || s.step_messages.iter().any(|m| m.contains(needle))
444	    }
445	
446	    /// Whether any captured success line contains `needle`.
447	    pub fn has_success(&self, needle: &str) -> bool {
448	        let s = self.state.borrow();
449	        s.step_successes.iter().any(|m| m.contains(needle))
450	    }
451	
452	    /// Whether any captured error contains `needle`.
453	    pub fn has_error(&self, needle: &str) -> bool {
454	        let s = self.state.borrow();
455	        s.step_errors.iter().any(|m| m.contains(needle))
456	    }
457	
458	    /// Whether any captured warning contains `needle`.
459	    pub fn has_warning(&self, needle: &str) -> bool {
460	        let s = self.state.borrow();
461	        s.step_warnings.iter().any(|m| m.contains(needle))
462	    }
463	
464	    /// All captured run headers.
465	    pub fn headers(&self) -> Vec<RunHeader> {
466	        self.state.borrow().headers.clone()
467	    }
468	
469	    /// All captured run summaries.
470	    pub fn summaries(&self) -> Vec<RunSummary> {
471	        self.state.borrow().summaries.clone()
472	    }
473	}
474	
475	impl WorkflowDisplay for MockWorkflowDisplay {
