521	impl MockStepDisplay {
522	    /// Construct a new mock step display sharing state with its
523	    /// parent [`MockWorkflowDisplay`].
524	    pub fn new(state: Rc<RefCell<MockState>>, index: usize, total: usize) -> Self {
525	        let step_number = format!("[{}/{}]", index + 1, total);
526	        let step_indent = step_number.chars().count() + 1;
