534	
535	impl crate::ui::OutputWriter for MockStepDisplay {
536	    fn message(&mut self, msg: &str) {
537	        self.state.borrow_mut().step_messages.push(msg.to_string());
538	    }
539	
540	    fn success(&mut self, msg: &str) {
541	        self.state.borrow_mut().step_successes.push(msg.to_string());
542	    }
