                    if !step.behavior.allow_failure {
                        failed_steps.insert(step_name.clone());
                    }
                    results.push(result);
                }

                StepAction::Blocked => {
                    all_success = false;
                    failed_steps.insert(step_name.clone());
                }

                StepAction::Aborted(result) => {
                    results.push(result);
                    workflow_aborted = true;
                    all_success = false;
                    break;
                }
            }

            // Update progress bar after step completes (reflects final position)
            workflow_display.update_progress(index + 1, total, start.elapsed());
        }

        // Flush satisfaction cache to disk
        if !options.dry_run {
            if let Err(e) = satisfaction_cache.flush() {
                tracing::warn!("Failed to flush satisfaction cache: {}", e);
            }
        }

        // Finish progress bar (clear before summary)
        workflow_display.finish_progress();

        let mut all_skipped: Vec<String> = plan.flag_skipped.into_iter().collect();
        all_skipped.extend(plan.env_skipped);

        let steps_run = results.len();
        let steps_skipped_count = all_skipped.len();
        let duration = start.elapsed();

        event_bus.emit(&BivvyEvent::WorkflowCompleted {
            name: workflow_name.to_string(),
            success: all_success,
            aborted: workflow_aborted,
            steps_run,
            steps_skipped: steps_skipped_count,
            duration_ms: duration.as_millis() as u64,
        });

        Ok(WorkflowResult {
            workflow: workflow_name.to_string(),
            steps: results,
            skipped: all_skipped,
            duration,
            success: all_success,
            aborted: workflow_aborted,
        })
    }
}

//! Interactive workflow orchestration.
//!
//! This module contains the interactive execution loop (`run_with_ui`) — the
//! workflow-level coordination layer. Step-level concerns (prompts, execution,
//! recovery, error display) are delegated to [`super::step_manager::StepManager`].
//!
//! Step execution with recovery is in [`super::execution`]. Prompt conversion
//! is in [`super::execution::config_prompt_to_ui_prompt`].

use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::time::Instant;

use crate::checks::CheckResult;
use crate::config::interpolation::InterpolationContext;
use crate::config::schema::StepOverride;
use crate::error::{BivvyError, Result};
use crate::logging::{BivvyEvent, EventBus, StepOutcomeKind};
use crate::requirements::checker::GapChecker;
use crate::state::satisfaction::{SatisfactionCache, SatisfactionRecord};
use crate::state::StateStore;
use crate::ui::UserInterface;

use super::display::WorkflowDisplay;
use super::plan::build_execution_plan;
use super::step_manager::{SkipCategory, StepAction, StepExecutionOptions, StepManager};
use super::workflow::{RunOptions, WorkflowResult, WorkflowRunner};

impl<'a> WorkflowRunner<'a> {
    /// Run a workflow with full interactive UI support.
    ///
    /// This is the primary execution entry point for interactive use. It manages
    /// the workflow lifecycle: building the execution plan, iterating over steps,
    /// updating the progress bar, tracking workflow state, and recording results.
    ///
    /// Step-level concerns (check evaluation, prompts, execution, recovery) are
    /// delegated to [`StepManager`].
    #[allow(clippy::too_many_arguments)]
    pub fn run_with_ui(
        &mut self,
        options: &RunOptions,
        context: &InterpolationContext,
        base_env: &HashMap<String, String>,
        process_env: &HashMap<String, String>,
        project_root: &Path,
        workflow_non_interactive: bool,
        step_overrides: &HashMap<String, StepOverride>,
        mut gap_checker: Option<&mut GapChecker<'_>>,
        state: Option<&mut StateStore>,
        satisfaction_cache: &mut SatisfactionCache,
        ui: &mut dyn UserInterface,
        workflow_display: &mut dyn WorkflowDisplay,
        event_bus: &mut EventBus,
    ) -> Result<WorkflowResult> {
        let start = Instant::now();
        let workflow_name = options.workflow.as_deref().unwrap_or("default");
        let mut context = context.clone();

        // Topological sort: compute execution order from the dependency graph.
        let graph = self.build_graph(workflow_name)?;
        let workflow_steps = &self.config.workflows[workflow_name].steps;
        // Pre-filter: remove steps excluded by --skip flags or only_environments mismatch.
        let plan = build_execution_plan(&graph, workflow_steps, options, &self.steps)?;

        let total = plan.steps_to_run.len();

        // Emit workflow started
        event_bus.emit(&BivvyEvent::WorkflowStarted {
            name: workflow_name.to_string(),
            step_count: total,
        });

        // Report pre-filtered steps before the loop begins.
        for skip_name in &plan.flag_skipped {
            event_bus.emit(&BivvyEvent::StepFilteredOut {
                name: skip_name.clone(),
                reason: "skip_flag".to_string(),
            });
            event_bus.emit(&BivvyEvent::StepOutcome {
                name: skip_name.clone(),
                outcome: StepOutcomeKind::FilteredOut,
                detail: Some("skip_flag".to_string()),
                duration_ms: None,
            });
            workflow_display.show_filtered_step(skip_name, "skipped");
        }
        for skip_name in &plan.env_skipped {
            event_bus.emit(&BivvyEvent::StepFilteredOut {
                name: skip_name.clone(),
                reason: "environment".to_string(),
            });
            let env_label = options.active_environment.as_deref().unwrap_or("unknown");
            event_bus.emit(&BivvyEvent::StepOutcome {
                name: skip_name.clone(),
                outcome: StepOutcomeKind::FilteredOut,
                detail: Some(format!("not in {} environment", env_label)),
                duration_ms: None,
            });
            workflow_display.show_filtered_step(
                skip_name,
                &format!("skipped (not in {} environment)", env_label),
            );
        }

        let interactive = ui.is_interactive() && !workflow_non_interactive;

        let mut results = Vec::new();
        let mut all_success = true;
        let mut failed_steps: HashSet<String> = HashSet::new();
        let mut user_skipped_steps: HashSet<String> = HashSet::new();
        let mut satisfied_steps: HashSet<String> = HashSet::new();
        let mut named_check_results: HashMap<String, CheckResult> = HashMap::new();
        let mut workflow_aborted = false;

        // Initialize the persistent progress bar (pinned at terminal bottom).
        workflow_display.start_progress(total);

        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
            let step =
                &self
                    .steps
                    .get(step_name)
                    .ok_or_else(|| BivvyError::ConfigValidationError {
                        message: format!("Step '{}' not found in resolved steps", step_name),
                    })?;

            // Update progress bar immediately — before execution, so the user
            // sees "Step N/M" the moment iteration reaches this step.
            workflow_display.update_progress(index + 1, total, start.elapsed());

            // Hand off to the step display for this iteration.
            let mut step_display = workflow_display.begin_step(index, total);

            // Create StepManager and delegate step-level execution
            let step_mgr = StepManager::new(step, step_name, index, total, &theme);

            let exec_opts = StepExecutionOptions {
                dry_run: options.dry_run,
                interactive,
                diagnostic_funnel: options.diagnostic_funnel,
                project_root,
                base_env,
                process_env,
                force_steps: &options.force,
                force_all: options.force_all,
                provided_requirements: &options.provided_requirements,
            };

            let action = step_mgr.execute(
                &exec_opts,
                &mut context,
                step_overrides,
                &mut gap_checker,
                &mut self.snapshot_store,
                &self.steps,
                state.as_deref(),
                satisfaction_cache,
                &failed_steps,
                &user_skipped_steps,
                &satisfied_steps,
                &mut named_check_results,
                &results,
                ui,
                step_display.as_mut(),
                event_bus,
            )?;

            // Update workflow state based on step action.
            // The workflow only tracks aggregate state (satisfied/failed/skipped sets)
            // — all per-step decisions are made by StepManager via the decision engine.
            match action {
                StepAction::Completed(result) => {
                    satisfied_steps.insert(step_name.clone());

                    // Record successful execution in satisfaction cache
                    let record = SatisfactionRecord {
                        satisfied: true,
                        source: crate::state::satisfaction::SatisfactionSource::ExecutionHistory,
                        recorded_at: chrono::Utc::now(),
                        evidence: crate::state::satisfaction::SatisfactionEvidence::HistoricalRun {
                            ran_at: chrono::Utc::now(),
                            exit_code: result.exit_code.unwrap_or(0),
                        },
                        config_hash: None,
                        step_hash: None,
                    };
                    satisfaction_cache.store(step_name, record);

                    results.push(result);
                }

                StepAction::Skipped(result, category) => {
                    // StepManager classifies the skip reason so the workflow
                    // doesn't need to inspect StepResult internals.
                    match category {
                        SkipCategory::Satisfied => {
                            satisfied_steps.insert(step_name.clone());
                        }
                        SkipCategory::UserDeclined | SkipCategory::DependencySkipped => {
                            user_skipped_steps.insert(step_name.clone());
                        }
                        SkipCategory::RecoverySkipped | SkipCategory::Other => {
                            // Recovery-skipped steps do NOT block dependents —
                            // the user chose to move past the failure.
                        }
                    }
                    results.push(result);
                }

                StepAction::Failed(result) => {
                    all_success = false;
                    if !step.behavior.allow_failure {
                        failed_steps.insert(step_name.clone());
                    }
                    results.push(result);
                }

                StepAction::Blocked => {
                    all_success = false;
                    failed_steps.insert(step_name.clone());
                }

                StepAction::Aborted(result) => {
                    results.push(result);
                    workflow_aborted = true;
                    all_success = false;
                    break;
                }
            }

            // Update progress bar after step completes (reflects final position)
            workflow_display.update_progress(index + 1, total, start.elapsed());
        }

        // Flush satisfaction cache to disk
        if !options.dry_run {
            if let Err(e) = satisfaction_cache.flush() {
                tracing::warn!("Failed to flush satisfaction cache: {}", e);
            }
        }

        // Finish progress bar (clear before summary)
        workflow_display.finish_progress();

        let mut all_skipped: Vec<String> = plan.flag_skipped.into_iter().collect();
        all_skipped.extend(plan.env_skipped);

        let steps_run = results.len();
        let steps_skipped_count = all_skipped.len();
        let duration = start.elapsed();

        event_bus.emit(&BivvyEvent::WorkflowCompleted {
            name: workflow_name.to_string(),
            success: all_success,
            aborted: workflow_aborted,
            steps_run,
            steps_skipped: steps_skipped_count,
            duration_ms: duration.as_millis() as u64,
        });

        Ok(WorkflowResult {
            workflow: workflow_name.to_string(),
            steps: results,
            skipped: all_skipped,
            duration,
            success: all_success,
            aborted: workflow_aborted,
        })
    }
}

//! Step execution with retry and interactive recovery.
//!
//! Extracted from `orchestrate.rs` to reduce its size. Contains the
//! execution lifecycle: spinner display, output capture, auto-retries,
//! and the interactive recovery menu.

use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::time::Instant;

use tracing::warn;

use crate::config::interpolation::InterpolationContext;
use crate::error::Result;
use crate::logging::{BivvyEvent, EventBus};
use crate::shell::OutputCallback;
use crate::steps::{execute_step, ExecutionOptions, ResolvedStep, StepResult, StepStatus};
use crate::ui::{format_duration, OutputMode, Prompt, PromptOption, PromptType, UserInterface};

use super::diagnostic;
use super::display::StepDisplay;
use super::patterns::{self, FixSuggestion, StepContext};
use super::recovery::{self, RecoveryAction};

/// Maximum total execution attempts per step (auto-retries + manual retries).
/// Prevents infinite loops when the recovery prompt always returns "retry"
/// (e.g., in test environments with MockUI).
const MAX_STEP_ATTEMPTS: u32 = 100;

/// Result of executing a step with the retry/recovery loop.
pub(super) struct StepExecutionResult {
    /// The final step result.
    pub result: StepResult,
    /// Whether the user chose to skip in the recovery menu.
    pub skipped_by_user: bool,
    /// Whether the user chose to abort in the recovery menu.
    pub aborted: bool,
}

/// Execute a step with retry and interactive recovery.
///
/// This handles the full execution lifecycle: spinner display, output capture,
/// auto-retries, and the interactive recovery menu (retry/fix/shell/skip/abort).
#[allow(clippy::too_many_arguments)]
pub(super) fn execute_step_with_recovery(
    step: &ResolvedStep,
    step_name: &str,
    step_number: &str,
    step_indent: usize,
    project_root: &Path,
    context: &InterpolationContext,
    base_env: &HashMap<String, String>,
    process_env: &HashMap<String, String>,
    needs_force: bool,
    dry_run: bool,
    interactive: bool,
    step_ctx: &StepContext<'_>,
    diagnostic_funnel: bool,
    workflow_state: &diagnostic::WorkflowState<'_>,
    ui: &mut dyn UserInterface,
    step_display: &mut dyn StepDisplay,
    event_bus: &mut EventBus,
) -> Result<StepExecutionResult> {
    let mut retry_count: u32 = 0;
    let mut fix_history: HashSet<String> = HashSet::new();
    let mut skipped_by_user = false;
    let mut aborted = false;
    #[allow(unused_assignments)]
    let mut final_result: Option<StepResult> = None;

    // Outer loop: step execution (retry/fix re-enter here)
    'step_execution: loop {
        // Fresh spinner per attempt — hide command text for sensitive steps
        let display_command = if step.behavior.sensitive {
            "[SENSITIVE]".to_string()
        } else {
            step.execution.command.clone()
        };
        // Mount the transient region with the spinner. The step display
        // owns the live-output ring buffer.
        step_display.start_running(&display_command);
        let output_mode = step_display.output_mode();
        let output_callback: Option<OutputCallback> = step_display.live_output_callback();

        let exec_options = ExecutionOptions {
            force: needs_force,
            dry_run,
            capture_output: output_callback.is_none(),
            ..Default::default()
        };
        let _ = step_number;

        let step_start = Instant::now();
        let result = match execute_step(
            step,
            project_root,
            context,
            base_env,
            process_env,
            &exec_options,
            output_callback,
        ) {
            Ok(result) => result,
            Err(e) => {
                warn!("Step '{}' errored: {}", step_name, e);
                StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
            }
        };

        // Emit StepOutput events for captured output
        if let Some(ref output) = result.output {
            for line in output.lines() {
                event_bus.emit(&BivvyEvent::StepOutput {
                    name: step_name.to_string(),
                    stream: "stdout".to_string(),
                    line: line.to_string(),
                });
            }
        }

        let duration_str = format_duration(result.duration);

        match result.status() {
            StepStatus::Completed => {
                let detail = if retry_count > 0 {
                    Some(format!("succeeded on retry (attempt {})", retry_count + 1))
                } else {
                    None
                };
                // Clear the transient region and write the final result
                // line into scrollback. The label is derived from the
                // status enum inside `finish`.
                step_display.finish(
                    StepStatus::Completed,
                    Some(result.duration),
                    detail.as_deref(),
                );
                let mut r = result;
                r.recovery_detail = detail;
                final_result = Some(r);
                break 'step_execution;
            }
            StepStatus::Skipped => {
                step_display.finish(StepStatus::Skipped, None, None);
                final_result = Some(result);
                break 'step_execution;
            }
            StepStatus::Failed => {
                step_display.finish(StepStatus::Failed, Some(result.duration), None);
                let _ = duration_str;

                // Build combined error output for pattern matching and display
                let combined_output = result
                    .output
                    .as_deref()
                    .map(|s| s.trim())
                    .filter(|s| !s.is_empty())
                    .unwrap_or_else(|| result.error.as_deref().unwrap_or("Command failed"))
                    .to_string();

                // Match against error recovery system
                let (fix, hint, resolutions) = if diagnostic_funnel {
                    let diag_ctx = diagnostic::StepContext {
                        name: step_ctx.name,
                        command: step_ctx.command,
                        requires: step_ctx.requires,
                        template: step_ctx.template,
                    };
                    let diag = diagnostic::diagnose(&combined_output, &diag_ctx, workflow_state);
                    // Collect all resolutions with confidence 0.1–0.29 as hint text
                    // (shown below error block, not in menu)
                    let hints: Vec<String> = diag
                        .resolutions
                        .iter()
                        .filter(|r| r.confidence >= 0.1 && r.confidence < 0.3)
                        .map(|r| r.label.clone())
                        .collect();
                    let hint = if hints.is_empty() {
                        None
                    } else {
                        Some(format!("You might try: {}", hints.join(", or ")))
                    };
                    (None, hint, diag.resolutions)
                } else {
                    let fix = patterns::find_fix(&combined_output, step_ctx);
                    let hint = patterns::find_hint(&combined_output, step_ctx);
                    (fix, hint, Vec::new())
                };

                // Show error block — skip in non-interactive verbose
                // where output was already streamed to stdout
                let output_was_streamed =
                    !step_display.is_interactive() && output_mode == OutputMode::Verbose;
                if !output_was_streamed {
                    step_display.show_error_block(
                        &step.execution.command,
                        &combined_output,
                        hint.as_deref(),
                        step_indent,
                    );
                }

                // allow_failure: record and move on, no recovery menu
                if step.behavior.allow_failure {
                    final_result = Some(result);
                    break 'step_execution;
                }

                // Auto-retry before showing recovery menu
                if retry_count < step.execution.retry {
                    retry_count += 1;
                    step_display.message(&format!(
                        "{}Retrying... (attempt {}/{})",
                        " ".repeat(step_indent),
                        retry_count + 1,
                        step.execution.retry + 1
                    ));
                    continue 'step_execution;
                }

                // Non-interactive: no recovery menu
                if !interactive {
                    final_result = Some(result);
                    break 'step_execution;
                }

                // Safety: cap total attempts to prevent infinite loops
                // (e.g., in tests where MockUI defaults to "retry")
                if retry_count >= MAX_STEP_ATTEMPTS {
                    warn!(
                        "Step '{}' exceeded max recovery attempts ({})",
                        step_name, MAX_STEP_ATTEMPTS
                    );
                    final_result = Some(result);
                    break 'step_execution;
                }

                // Interactive recovery menu
                handle_recovery_menu(
                    step,
                    step_name,
                    step_indent,
                    result,
                    &combined_output,
                    fix,
                    hint,
                    &resolutions,
                    diagnostic_funnel,
                    &mut fix_history,
                    &mut retry_count,
                    &mut skipped_by_user,
                    &mut aborted,
                    &mut final_result,
                    project_root,
                    base_env,
                    process_env,
                    ui,
                    step_display,
                    event_bus,
                )?;
                if final_result.is_some() {
                    break 'step_execution;
                }
                // If final_result is still None, recovery chose retry/fix → continue
                continue 'step_execution;
            }
            _ => {
                final_result = Some(result);
                break 'step_execution;
            }
        }
    }

    Ok(StepExecutionResult {
        result: final_result.expect("step execution loop must produce a result"),
        skipped_by_user,
        aborted,
    })
}

/// Handle the interactive recovery menu after a step failure.
///
/// Sets `final_result` if the user chose to skip or abort. Returns `Ok(())`
/// to let the caller decide whether to continue or break the execution loop.
#[allow(clippy::too_many_arguments)]
fn handle_recovery_menu(
    step: &ResolvedStep,
    step_name: &str,
    step_indent: usize,
    result: StepResult,
    combined_output: &str,
    fix: Option<FixSuggestion>,
    hint: Option<String>,
    resolutions: &[diagnostic::ResolutionCandidate],
    diagnostic_funnel: bool,
    fix_history: &mut HashSet<String>,
    retry_count: &mut u32,
    skipped_by_user: &mut bool,
    aborted: &mut bool,
    final_result: &mut Option<StepResult>,
    project_root: &Path,
    base_env: &HashMap<String, String>,
    process_env: &HashMap<String, String>,
    ui: &mut dyn UserInterface,
    step_display: &mut dyn StepDisplay,
    event_bus: &mut EventBus,
) -> Result<()> {
    let pad = " ".repeat(step_indent);
    event_bus.emit(&BivvyEvent::RecoveryStarted {
        step: step_name.to_string(),
        error: combined_output.to_string(),
    });
    let has_hint = hint.is_some();
    loop {
        let action = if diagnostic_funnel {
            recovery::prompt_recovery_multi(ui, step_name, resolutions, fix_history, step_indent)?
        } else {
            recovery::prompt_recovery(
                ui,
                step_name,
                fix.as_ref(),
                has_hint,
                fix_history,
                step_indent,
            )?
        };

        match action {
            RecoveryAction::Retry => {
                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
                    step: step_name.to_string(),
                    action: "retry".to_string(),
                    command: None,
                });
                *retry_count += 1;
                return Ok(());
            }
            RecoveryAction::Fix(ref cmd) | RecoveryAction::CustomFix(ref cmd) => {
                let is_custom = matches!(action, RecoveryAction::CustomFix(_));
                let cmd = cmd.clone();
                if recovery::confirm_fix(ui, step_name, &cmd)? {
                    event_bus.emit(&BivvyEvent::RecoveryActionTaken {
                        step: step_name.to_string(),
                        action: if is_custom {
                            "custom_fix".to_string()
                        } else {
                            "fix".to_string()
                        },
                        command: Some(cmd.clone()),
                    });
                    let fix_ok = recovery::run_fix(&cmd, project_root, &step.env_vars.env)?;
                    fix_history.insert(cmd.clone());
                    if fix_ok {
                        step_display.message(&format!("{}Fix command succeeded.", pad));
                    } else {
                        step_display.message(&format!("{}Fix command failed.", pad));
                    }
                    *retry_count += 1;
                    return Ok(());
                }
                // User declined the fix — re-show recovery menu
            }
            RecoveryAction::Shell => {
                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
                    step: step_name.to_string(),
                    action: "shell".to_string(),
                    command: None,
                });
                step_display.message(&format!(
                    "{}Dropping to debug shell (exit to return)...",
                    pad
                ));
                let debug_env =
                    crate::steps::build_step_env(step, project_root, base_env, process_env)?;
                crate::shell::debug::spawn_debug_shell(step_name, project_root, &debug_env)?;
                // After shell exit, re-show recovery menu
            }
            RecoveryAction::Skip => {
                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
                    step: step_name.to_string(),
                    action: "skip".to_string(),
                    command: None,
                });
                *skipped_by_user = true;
                let mut r = result;
                r.recovery_detail = Some("skipped by user after failure".to_string());
                *final_result = Some(r);
                return Ok(());
            }
            RecoveryAction::Abort => {
                event_bus.emit(&BivvyEvent::RecoveryActionTaken {
                    step: step_name.to_string(),
                    action: "abort".to_string(),
                    command: None,
                });
                *aborted = true;
                let mut r = result;
                r.recovery_detail = Some("aborted by user".to_string());
                *final_result = Some(r);
                return Ok(());
            }
        }
    }
}

/// Convert a config-level PromptConfig into a UI Prompt.
pub(super) fn config_prompt_to_ui_prompt(config: &crate::config::schema::PromptConfig) -> Prompt {
    use crate::config::schema::PromptType as ConfigPromptType;

    let default = config.default.as_ref().and_then(|v| match v {
        serde_yaml::Value::String(s) => Some(s.clone()),
        serde_yaml::Value::Bool(b) => Some(b.to_string()),
        serde_yaml::Value::Number(n) => Some(n.to_string()),
        _ => None,
    });

    let prompt_type = match &config.prompt_type {
        ConfigPromptType::Select => PromptType::Select {
            options: config
                .options
                .iter()
                .map(|o| PromptOption {
                    label: o.label.clone(),
                    value: o.value.clone(),
                })
                .collect(),
        },
        ConfigPromptType::Multiselect => PromptType::MultiSelect {
            options: config
                .options
                .iter()
                .map(|o| PromptOption {
                    label: o.label.clone(),
                    value: o.value.clone(),
                })
                .collect(),
        },
        ConfigPromptType::Confirm => PromptType::Confirm,
        ConfigPromptType::Input => PromptType::Input,
    };

    Prompt {
        key: config.key.clone(),
        question: config.question.clone(),
        prompt_type,
        default,
    }
}

